!function(){function createGlassButton(options={}){const button=document.createElement("button");return button.type=options.type||"button",button.className=("glass-btn "+(options.primary?"glass-btn--primary":"")).trim(),button.textContent=options.label||"Button","function"==typeof options.onClick&&button.addEventListener("click",options.onClick),button}window.LiquidGlassUI={createGlassButton:createGlassButton,createGlassCard:function(options={}){const card=document.createElement("article");if(card.className="glass-surface",card.style.borderRadius="20px",card.style.padding="20px",options.title){const title=document.createElement("h3");title.textContent=options.title,title.style.margin="0 0 8px",card.appendChild(title)}if(options.body){const body=document.createElement("p");body.textContent=options.body,body.style.margin="0",card.appendChild(body)}return card},createGlassPricingCard:function(options={}){const card=document.createElement("article");return card.className=("glass-pricing-card "+(options.featured?"glass-pricing-card--featured":"")).trim(),card.innerHTML=`\n      <p class="glass-pricing-card__tag">${options.tag||"Plan"}</p>\n      <h3>${options.title||"Standard"}</h3>\n      <p class="glass-pricing-card__price">${options.price||"$0"}<span>${options.period||"/month"}</span></p>\n      <ul>${(options.features||[]).map(item=>`<li>${item}</li>`).join("")}</ul>\n    `,card.appendChild(createGlassButton({label:options.buttonLabel||"Choose Plan",primary:Boolean(options.featured),onClick:options.onClick})),card}}}();